import random
import string

def number_generator(valid=True):
    """Generate valid or invalid numbers in string format."""

    digits = string.digits
    signs = '+-'
    alphabet = string.ascii_lowercase + string.ascii_uppercase
    optional_e = 'eE'

    while True:
        if valid:
            number = ''
            # A sign character (either '+' or '-')
            if random.choice([True, False]):
                number += random.choice(signs)

            # One or more digits
            number += ''.join(random.choice(digits) for _ in range(random.randint(1, 4)))

            # A dot '.', followed by one or more digits
            if random.choice([True, False]):
                number += '.'
                number += ''.join(random.choice(digits) for _ in range(random.randint(1, 4)))

            # An 'e' or 'E', followed by an integer
            if random.choice([True, False]):
                number += random.choice(optional_e)
                if random.choice([True, False]):
                    number += random.choice(signs)
                number += ''.join(random.choice(digits) for _ in range(random.randint(1, 4)))

            return number

        else:
            # Start with a digit or alphabet character
            number = random.choice(digits + alphabet)

            # Continue adding random characters
            number += ''.join(random.choice(digits + alphabet + signs + '.eE') 
                              for _ in range(random.randint(1, 9)))

            return number

def generate_test_case():
    return number_generator()
